export type ObjectiveStatus =
  | 'draft'
  | 'open'
  | 'assigned'
  | 'in_progress'
  | 'under_evaluation'
  | 'completed'
  | 'cancelled'

export type ObjectiveTab = 'about' | 'assign' | 'deliver' | 'evaluate' | 'complete'

export type ValueMode = 'fixed' | 'variable' | 'milestone' | 'none'

export type ObjectiveParticipant = {
  userId: string
  displayName: string
  avatarUrl?: string
  role: 'owner' | 'contributor' | 'evaluator' | 'viewer'
  agreementStatus: 'pending' | 'accepted' | 'declined'
}

export type Objective = {
  id: string
  projectId: string
  title: string
  description?: string
  status: ObjectiveStatus
  startDate?: string
  endDate?: string
  tags: string[]
  participants: ObjectiveParticipant[]
  valueMode: ValueMode
  assignedValue?: number
  currency?: string
  tasksCount: number
  completedTasksCount: number
  createdAt: string
  updatedAt: string
}

export type ObjectiveEvaluation = {
  id: string
  objectiveId: string
  evaluatorId: string
  evaluatorName: string
  rating: number
  feedback?: string
  createdAt: string
}
